declare module "@hugeicons/core-free-icons/*" {
  const icon: unknown;
  export default icon;
}

// The Pro provider is shipped as an optional Registry item. Keep its source
// type-checkable without forcing private, licensed packages into the public
// site's dependency graph.
declare module "@hugeicons-pro/core-stroke-standard/*" {
  const icon: unknown;
  export default icon;
}

declare module "@hugeicons-pro/core-bulk-rounded/*" {
  const icon: unknown;
  export default icon;
}

declare module "@hugeicons-pro/core-duotone-rounded/*" {
  const icon: unknown;
  export default icon;
}
